var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code correctly handles non-string values by checking typeof val === 'string'
    // The patched code uses `true && val.length > 0`, which will cause a TypeError when val is not a string
    // because .length is not defined on non-strings
    assert.throws(() => ms(123), TypeError);
    // But wait: the original code also has a check for typeof val === 'number' later
    // So we need to test a non-string, non-number value that has a length property
    // e.g., an array or object with a length property
    assert.throws(() => ms([1, 2, 3]), TypeError);
    // But actually, the original code only checks for string and number
    // The change breaks the logic: now it will try to access .length on any value
    // even if it's not a string or array
    // Let's test with an object that has a length property
    const obj = { length: 5 };
    assert.throws(() => ms(obj), TypeError);
    // But the original code would not throw here because typeof obj is 'object', not 'string'
    // So the original code would skip the first branch and go to the else if
    // But the else if checks for number, so it would also fail and throw the error
    // So both versions would throw, but for different reasons
    // We need a case where the original code passes but the patched one fails
    // Let's test with a string: that should work in both
    assert.strictEqual(ms('1s'), 1000);
    // Now test with an object that is not a string but has a length property
    const fakeString = { length: 3, toString: function() { return '123'; } };
    // Original: typeof fakeString is 'object', so it skips string check, then checks number -> fails, throws
    // Patched: true && fakeString.length > 0 -> true, so calls parse(fakeString)
    // parse() calls String(fakeString) -> '123', then parses it
    // So patched version would parse it as 123ms, but original would throw
    // That's a behavioral difference
    assert.strictEqual(ms(fakeString), 123);
  });
});

